using System;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Windows.Forms;using System.Collections.Generic;using System.Runtime.Serialization.Json;
namespace Frociart.Tests {static class TutorArrangeTests {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static int checks;static string folder;
 static void Check(bool b,string t){if(!b)throw new Exception(t);checks++;Console.WriteLine("PASS "+t);}
 static T Get<T>(object o,string n){return (T)o.GetType().GetField(n,F).GetValue(o);}
 static object Call(object o,string n,params object[] a){return o.GetType().GetMethods(F).First(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(o,a);}
 static IEnumerable<Control> Walk(Control c){yield return c;foreach(Control child in c.Controls)foreach(var v in Walk(child))yield return v;}
 static void Pump(int ms){var end=DateTime.UtcNow.AddMilliseconds(ms);do{Application.DoEvents();Thread.Sleep(3);}while(DateTime.UtcNow<end);}
 static string Bytes(Diagram d){using(var m=new MemoryStream()){new DataContractJsonSerializer(typeof(Diagram)).WriteObject(m,d);return Convert.ToBase64String(m.ToArray());}}
 static void Shot(FlowCanvas c,string name){using(var b=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(b,c.ClientRectangle);b.Save(Path.Combine(folder,name+".png"));}}
 [STAThread]static int Main(){try{Application.EnableVisualStyles();UiMotion.SetEnabled(true);Ui.SetDarkMode(true,false);folder=Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"tutor-reorder");Directory.CreateDirectory(folder);
 using(var d=new TutorDialog(new TutorStore(),new LearningStore())){d.ShowInTaskbar=false;d.StartPosition=FormStartPosition.Manual;d.Location=new Point(-4000,-3000);d.Show();Pump(150);d.OpenWorkshop();Pump(300);d.Current.Document=Examples.Parity();var c=d.Canvas;c.Diagram=d.Current.Document;var n=d.Current.Document.Nodes.First(x=>x.Id=="check");n.X+=180;n.Y+=80;c.FitToView();Pump(300);string original=Bytes(d.Current.Document);var before=(RectangleF)Call(c,"DisplayBounds",n);Shot(c,"01-before");
 ((Button)Walk(d).First(v=>v is Button&&v.Text=="Riordina")).PerformClick();
 Check(Get<object>(c,"settleFrom")!=null&&Get<bool>(c,"arrangeCamera"),"Guided Riordina starts both node and camera transition");var start=(RectangleF)Call(c,"DisplayBounds",n);Check(Math.Abs(start.X-before.X)<12&&Math.Abs(start.Y-before.Y)<12,"Guided Riordina begins at the previous displayed geometry");string final=Bytes(d.Current.Document);Shot(c,"02-start");Pump(100);var middle=(RectangleF)Call(c,"DisplayBounds",n);Check(middle!=start,"Guided Riordina has intermediate geometry");Shot(c,"03-middle");Check(Bytes(d.Current.Document)==final,"Animation keeps final document coordinates stable");Pump(430);Check(Get<object>(c,"settleFrom")==null&&!Get<bool>(c,"arrangeCamera"),"Guided Riordina completes and stops both transitions");Shot(c,"04-settled");Check(Get<Stack<TutorSession>>(d,"undo").Count==1,"Guided Riordina has exactly one Undo");((Button)Walk(d).First(v=>v is Button&&v.AccessibleName=="Annulla")).PerformClick();Pump(100);Check(Bytes(d.Current.Document)==original,"Guided Riordina Undo restores all original coordinates and edges");
 UiMotion.SetEnabled(false);((Button)Walk(d).First(v=>v is Button&&v.Text=="Riordina")).PerformClick();Check(Get<object>(c,"settleFrom")==null&&!Get<bool>(c,"arrangeCamera"),"Guided Riordina respects reduced motion");UiMotion.SetEnabled(true);d.Close();}
 Console.WriteLine("TUTOR_ARRANGE_FINISHED checks="+checks+" errors=0");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}}
